lines=[json.loads(l) for l in open('transcripts/harness_db856d85/main.jsonl',encoding='utf-8')]
def text(d):
    out=[]
    c = d.get('content') if d.get('type')=='queue-operation' else (d.get('message') or {}).get('content') if d.get('type')=='user' else None
